19	#define DEBUG_TYPE "add-memory-token"
20	
21	/*
22	 * This Pass file aims to add memory tokens automatically to ensure tileIR's
23	 * compatibility with Triton. We add memory tokens based on the following rules:
24	 *  - If a kernel contains memory ops with input token, which means user has
25	 * already added some tokens in the kernel, we will keep the original token flow
26	 * unchanged and do nothing.
27	 *  - If a kernel contains a triton debug_barrier op, we add memory tokens for
28	 * all memory ops in a sequential way.
29	 *  - If a kernel contains sets of memory ops which acesses the same data, we
30	 * will apply memory tokens to maintain their access order.
31	 *
32	 * Implementation:
33	 *  We organize memory ops into sequances, where each sequence access the same
34	 * memory data and their access order need to be maintained by memory token. To
35	 * distinguish different sequances, we assign SID for each sequence and add
36	 * function getMemOpSeqId to map op to its sequence SID. There are 2 types of
37	 * memory ops:
38	 *    - one is ptr memory ops, which uses tensor of pointers like LoadPtrTkoOp.
39	 *    - the other is view memory ops, which uses tensor of views like
40	 * LoadViewTkoOp. These two kind of memory ops use different ways to represent
41	 * their memory accessing pattern. So for ptr memory ops, we hash their ptr
42	 * value as SID; for view ops, we hash their view value and index values as SID.
43	 *  The main transformation is done in Pass AutoGenMemoryTokenPass, which
44	 * performs two walks for the entire input IR. One is to collect memory sequence
45	 * info, and after processing collected data (to make sure there are memory
46	 * tokens required to be added), another walk is performed to add memory tokens
47	 * based on the sequence info.
48	 *
49	 * In this version of implementation, there are some scenarios we cannot handle:
50	 *    1. if some ptr ops and view ops access the same data, we will not be able
51	 * to detect that and put them into the same sequence.
52	 *    2. if some memory ops' access memory overlap, we will not be able to find
53	 * out.
54	 *    3. if users pass 2 ptrs pointing to the same memory location, we will not
55	 * be able to find out.
56	 */
57	
58	namespace {
59	
60	using namespace mlir::triton;
61	
62	using SeqId = std::size_t;
63	using SeqIdSet = llvm::SmallSet<SeqId, 16>;
64	using SeqIdVec = SmallVector<SeqId>;
65	static const SeqId BARRIER_SEQ_ID = 1;
66	
67	using SeqTokensBase = DenseMap<SeqId, Value>;
68	class SeqTokens : public SeqTokensBase {
69	  SeqIdSet updatedSids;
70	
71	public:
72	  SeqTokens() = default;
73	
74	  void update(SeqId id, Value token) {
75	    (*this)[id] = token;
76	    updatedSids.insert(id);
77	  }
78	
79	  void update(const SeqTokens &newTokens) {
80	    for (const auto &pair : newTokens)
81	      update(pair.first, pair.second);
82	  }
83	
84	  SeqIdVec
85	  aggregate(const SmallVector<std::reference_wrapper<SeqTokens>> &tokenSets) {
86	    SeqIdSet allUpdatedSids;
87	    for (auto &tokenRef : tokenSets) {
88	      for (const auto &p : tokenRef.get())
89	        allUpdatedSids.insert(p.first);
90	    }
91	
92	    // Here we use a vector to make sure all results have the same sid order
93	    SeqIdVec allUpdatedSidsVec(allUpdatedSids.begin(), allUpdatedSids.end());
94	
95	    auto genResult = [&](SeqTokens &tokens) {
96	      for (const auto &sid : allUpdatedSidsVec) {
97	        if (tokens.find(sid) == tokens.end())
98	          tokens[sid] = (*this)[sid];
99	      }
100	    };
101	
102	    for (auto &tokenRef : tokenSets)
103	      genResult(tokenRef.get());
104	
105	    return allUpdatedSidsVec;
106	  }
107	
108	  SeqTokens getUpdatedTokens() {
109	    SeqTokens outTokens;
110	    for (const auto &sid : updatedSids)
111	      outTokens[sid] = (*this)[sid];
112	    return outTokens;
113	  }
114	
115	  void cleanUpdatedSids() { updatedSids.clear(); }
116	};
117	using OpToTokens = SmallVector<std::pair<Operation *, SeqTokens>, 4>;
118	
119	struct MemSeqInfo {
120	  size_t writeMemOpCounter = 0;
121	  size_t memOpCounter = 0; // used for both preprocessing and transform
122	  bool ignored = false;
123	
124	  MemSeqInfo() = default;
125	};
126	
127	struct BlockMemSeqs {
128	  // collected data from preprocessing walk
129	  bool hasBarrierOp = false;
130	  bool hasMemToken = false;
131	  DenseMap<SeqId, MemSeqInfo> srcToMemSeqInfoMap;
132	
133	  // runtime data for transform walk
134	  int loop_level = 0;
135	  int if_level = 0;
136	
137	  BlockMemSeqs() = default;
138	  SeqTokens getBlockInitTokens(Block *block, IRRewriter &rewriter) {
139	    rewriter.setInsertionPointToStart(block);
140	    SeqTokens tokens;
141	    for (const auto &pair : srcToMemSeqInfoMap) {
142	      if (pair.second.ignored)
143	        continue; // only make new token for un-ignored sequences
144	      auto makeTkOp =
145	          cuda_tile::MakeTokenOp::create(rewriter, block->front().getLoc());
146	      tokens[pair.first] = makeTkOp.getResult();
147	    }
148	    return tokens;
149	  }
150	
151	  void clear() {
152	    hasBarrierOp = false;
153	    hasMemToken = false;
154	    loop_level = 0;
155	    if_level = 0;
156	    srcToMemSeqInfoMap.clear();
157	  }
158	};
159	
160	bool isMemOp(Operation *op) {
161	  return isa<cuda_tile::LoadPtrTkoOp, cuda_tile::StorePtrTkoOp,
162	             cuda_tile::LoadViewTkoOp, cuda_tile::StoreViewTkoOp,
163	             cuda_tile::AtomicRMWTkoOp, cuda_tile::AtomicCASTkoOp>(op);
164	}
165	
166	bool isWriteMemOp(Operation *op) {
167	  return isa<cuda_tile::StorePtrTkoOp, cuda_tile::StoreViewTkoOp,
168	             cuda_tile::AtomicRMWTkoOp, cuda_tile::AtomicCASTkoOp>(op);
169	}
