171	class AutoGenMemoryTokenPass
172	    : public ::mlir::triton::impl::AutoGenMemoryTokenBase<
173	          AutoGenMemoryTokenPass> {
174	  // Data members
175	  BlockMemSeqs currentBlockMemSeqs;
176	
177	  /// Generate SeqId for a specific memory op
178	  SeqId getMemOpSeqId(Operation *op) {
179	    if (currentBlockMemSeqs.hasBarrierOp)
180	      return BARRIER_SEQ_ID;
181	
182	    Value val = Value();
183	    SmallVector<Value> indexes;
184	    if (auto loadOp = dyn_cast<cuda_tile::LoadPtrTkoOp>(op)) {
185	      val = loadOp.getSource();
186	      if (loadOp.getToken())
187	        currentBlockMemSeqs.hasMemToken = true;
188	    } else if (auto storeOp = dyn_cast<cuda_tile::StorePtrTkoOp>(op)) {
189	      val = storeOp.getDestination();
190	      if (storeOp.getToken())
191	        currentBlockMemSeqs.hasMemToken = true;
192	    } else if (auto atmRMWOp = dyn_cast<cuda_tile::AtomicRMWTkoOp>(op)) {
193	      val = atmRMWOp.getPointers();
194	      if (atmRMWOp.getToken())
195	        currentBlockMemSeqs.hasMemToken = true;
196	    } else if (auto atmCASOp = dyn_cast<cuda_tile::AtomicCASTkoOp>(op)) {
197	      val = atmCASOp.getPointers();
198	      if (atmCASOp.getToken())
199	        currentBlockMemSeqs.hasMemToken = true;
200	    } else if (auto viewOp = dyn_cast<cuda_tile::LoadViewTkoOp>(op)) {
201	      val = viewOp.getView();
202	      indexes = viewOp.getIndex();
203	      if (viewOp.getToken())
204	        currentBlockMemSeqs.hasMemToken = true;
205	    } else if (auto viewOp = dyn_cast<cuda_tile::StoreViewTkoOp>(op)) {
206	      val = viewOp.getView();
207	      indexes = viewOp.getIndex();
208	      if (viewOp.getToken())
209	        currentBlockMemSeqs.hasMemToken = true;
210	    }
211	    // TODO: does different order of index generate the same hash value?
212	    if (!val)
213	      return 0;
214	    llvm::hash_code hash = mlir::hash_value(val);
215	    for (const Value &val : indexes)
216	      hash = llvm::hash_combine(hash, mlir::hash_value(val));
217	    return hash;
218	  }
219	
220	  /// Get function/entry block and name from operation
221	  Block *getFuncBlock(Operation *op, std::string &funcName) {
222	    if (auto entryOp = dyn_cast<cuda_tile::EntryOp>(op)) {
223	      funcName = entryOp.getSymName().str();
224	      return &entryOp.getBody().front();
225	    }
226	    return nullptr;
227	  }
228	
229	  /// Handle memory op
230	  /// 1. add input token to op's operands(if token is not null)
231	  /// 2. update operandSegmentSizes attribute(if exists)
232	  /// 3. return the updated token value from op's result values.
233	  template <typename OpTy>
234	  Value updateMemOpWithToken(OpTy *op, Value token, IRRewriter &rewriter) {
235	    SmallVector<Value> newOperands = llvm::to_vector(op->getOperands());
236	
237	    if (token) {
238	      // append token operand
239	      newOperands.push_back(token);
240	      // update operand segment sizes attribute
241	      if (auto segmentSizesAttr = op->getAttr("operandSegmentSizes")) {
242	        auto arrayAttr = dyn_cast<DenseI32ArrayAttr>(segmentSizesAttr);
243	        SmallVector<int32_t> newSegmentSizes =
244	            llvm::to_vector(arrayAttr.asArrayRef());
245	        newSegmentSizes.back() =
246	            1; // the last segment indicates whether token operand exists
247	        op->setAttr("operandSegmentSizes",
248	                    rewriter.getDenseI32ArrayAttr(newSegmentSizes));
249	      }
250	    }
251	    op->setOperands(newOperands);
252	
253	    return op->getResults().back();
254	  }
255	
256	  /// Handle terminator ops by adding token to its operands.
257	  template <typename OpTy>
258	  void updateTermOpWithToken(OpTy *op, SeqTokens &tokens, SeqIdVec &sids) {
259	    SmallVector<Value> newOperands = llvm::to_vector(op->getOperands());
260	    // use sids to ensure the order of tokens
261	    for (auto s : sids)
262	      newOperands.push_back(tokens[s]);
263	    op->setOperands(newOperands);
264	  }
265	
266	  SeqTokens handleIfOpTokens(cuda_tile::IfOp ifOp, SeqTokens tokens,
267	                             IRRewriter &rewriter, OpToTokens *termOps) {
268	    tokens.cleanUpdatedSids();
269	    currentBlockMemSeqs.if_level++;
270	
271	    // handle token in then and else block
272	    SeqTokens thenTokens =
273	        addMemTokenForBlock(ifOp.getThenBlock(), tokens, rewriter, termOps);
274	    SeqTokens elseTokens =
275	        addMemTokenForBlock(ifOp.getElseBlock(), tokens, rewriter, termOps);
276	    SmallVector<std::reference_wrapper<SeqTokens>> tokenList{
277	        std::ref(thenTokens), std::ref(elseTokens)};
278	    SeqIdVec sids = tokens.aggregate(tokenList);
279	
280	    // skip those sequences which will not be used in later memory ops
281	    if (!currentBlockMemSeqs.loop_level) {
282	      SeqIdVec newSids;
283	      for (const auto &sid : sids) {
284	        if (currentBlockMemSeqs.srcToMemSeqInfoMap[sid].memOpCounter == 0) {
285	          thenTokens.erase(thenTokens.find(sid));
286	          elseTokens.erase(elseTokens.find(sid));
287	        } else
288	          newSids.push_back(sid);
289	      }
290	      sids.swap(newSids);
291	    }
292	
293	    auto insertTermOp = [&]() {
294	      rewriter.createBlock(&ifOp.getElseRegion());
295	      rewriter.setInsertionPointToEnd(ifOp.getElseBlock());
296	      cuda_tile::YieldOp::create(rewriter, ifOp.getLoc());
297	    };
298	
299	    // if either branch has memory token update, we need to update terminate ops
300	    // of this ifOp
301	    if (!sids.empty() && isa<cuda_tile::YieldOp>(ifOp.getThenTerminator())) {
302	      updateTermOpWithToken(ifOp.getThenTerminator(), thenTokens, sids);
303	      if (!ifOp.getElseTerminator())
304	        insertTermOp();
305	      updateTermOpWithToken(ifOp.getElseTerminator(), elseTokens, sids);
306	
307	      // append token type to ifOp's return type
308	      rewriter.setInsertionPointAfter(ifOp);
309	      SmallVector<Type> resultTypes = llvm::to_vector(ifOp.getResultTypes());
310	      resultTypes.append(sids.size(),
311	                         cuda_tile::TokenType::get(rewriter.getContext()));
312	      auto newIfOp =
313	          cuda_tile::IfOp::create(rewriter, ifOp.getLoc(), resultTypes,
314	                                  ifOp.getCondition(), ifOp->getAttrs());
315	      rewriter.inlineRegionBefore(ifOp.getThenRegion(), newIfOp.getThenRegion(),
316	                                  newIfOp.getThenRegion().begin());
317	      rewriter.inlineRegionBefore(ifOp.getElseRegion(), newIfOp.getElseRegion(),
318	                                  newIfOp.getElseRegion().begin());
319	      // update token
320	      for (size_t i = 0; i < sids.size(); i++)
321	        tokens.update(sids[i], newIfOp.getResult(ifOp.getNumResults() + i));
322	
323	      // replace old result values with new ones, except new token
324	      SmallVector<Value> replacementResults;
325	      for (size_t i = 0; i < ifOp.getNumResults(); i++)
326	        replacementResults.push_back(newIfOp.getResult(i));
327	      rewriter.replaceOp(ifOp, replacementResults);
328	    } else if (isa<cuda_tile::BreakOp, cuda_tile::ContinueOp>(
329	                   ifOp.getThenTerminator())) {
330	      if (!ifOp.getElseTerminator())
331	        insertTermOp();
332	      if (termOps == nullptr) {
333	        ifOp.emitWarning("unexpected terminator op in if op");
334	      } else {
335	        termOps->push_back({ifOp.getThenTerminator(), thenTokens});
336	        termOps->push_back({ifOp.getElseTerminator(), elseTokens});
337	      }
338	    }
339	
340	    currentBlockMemSeqs.if_level--;
341	    return tokens.getUpdatedTokens();
342	  }
343	
344	  SeqTokens handleForOpTokens(cuda_tile::ForOp forOp, SeqTokens tokens,
345	                              IRRewriter &rewriter) {
346	    tokens.cleanUpdatedSids();
347	    currentBlockMemSeqs.loop_level++;
348	
349	    // handle token in body block
350	    OpToTokens localTermOps;
351	    SeqTokens forTokens =
352	        addMemTokenForBlock(forOp.getBody(), tokens, rewriter, &localTermOps);
353	    SmallVector<std::reference_wrapper<SeqTokens>> tokenList{
354	        std::ref(forTokens)};
355	    for (auto &opTokenPair : localTermOps)
356	      tokenList.push_back(std::ref(opTokenPair.second));
357	    SeqIdVec sids = tokens.aggregate(tokenList);
358	
359	    // add token to terminator
360	    if (!sids.empty()) {
361	      // add token to terminator recursively
362	      updateTermOpWithToken(forOp.getBody()->getTerminator(), forTokens, sids);
363	      for (auto &pair : localTermOps)
364	        updateTermOpWithToken(pair.first, pair.second, sids);
365	
366	      // append token type to forOp's init values
367	      SmallVector<Value> newInitArgs = llvm::to_vector(forOp.getInitValues());
368	      for (const auto &sid : sids)
369	        newInitArgs.push_back(tokens[sid]);
370	      // create new loop op
371	      rewriter.setInsertionPointAfter(forOp);
372	      auto newForOp = cuda_tile::ForOp::create(
373	          rewriter, forOp.getLoc(), forOp.getLowerBound(),
374	          forOp.getUpperBound(), forOp.getStep(), newInitArgs);
375	
376	      // copy block body
377	      Block *newBlock = &newForOp.getRegion().front();
378	      SmallVector<Value> blockArgs;
379	      size_t originNumArgs = forOp.getBody()->getNumArguments();
380	      for (auto arg : forOp.getBody()->getArguments())
381	        blockArgs.push_back(newBlock->getArgument(arg.getArgNumber()));
382	      rewriter.mergeBlocks(forOp.getBody(), newBlock, blockArgs);
383	
384	      // update token usage in loop body
385	      for (size_t i = 0; i < sids.size(); i++) {
386	        auto arg = newBlock->getArgument(originNumArgs + i);
387	        tokens[sids[i]].replaceAllUsesExcept(arg, newForOp);
388	        tokens.update(sids[i], newForOp.getResult(forOp.getNumResults() + i));
389	      }
390	
391	      // replace old result values with new ones, except new token
392	      SmallVector<Value> replacementResults;
393	      for (size_t i = 0; i < forOp.getNumResults(); i++)
394	        replacementResults.push_back(newForOp.getResult(i));
395	      rewriter.replaceOp(forOp, replacementResults);
396	    }
397	
398	    currentBlockMemSeqs.loop_level--;
399	    return tokens.getUpdatedTokens();
400	  }
401	
402	  SeqTokens handleLoopOpTokens(cuda_tile::LoopOp loopOp, SeqTokens tokens,
403	                               IRRewriter &rewriter) {
404	    tokens.cleanUpdatedSids();
405	    currentBlockMemSeqs.loop_level++;
406	
407	    // handle token in body block
408	    OpToTokens localTermOps;
409	    SeqTokens loopTokens =
410	        addMemTokenForBlock(loopOp.getBody(), tokens, rewriter, &localTermOps);
411	    SmallVector<std::reference_wrapper<SeqTokens>> tokenList{
412	        std::ref(loopTokens)};
413	    for (auto &opTokenPair : localTermOps)
414	      tokenList.push_back(std::ref(opTokenPair.second));
415	    SeqIdVec sids = tokens.aggregate(tokenList);
416	
417	    // add token to terminator
418	    if (!sids.empty()) {
419	      // add token to terminator recursively
420	      updateTermOpWithToken(loopOp.getBody()->getTerminator(), loopTokens,
421	                            sids);
422	      for (auto &pair : localTermOps)
423	        updateTermOpWithToken(pair.first, pair.second, sids);
424	
425	      // append token type to loopOp's operand
426	      SmallVector<Value> newOperands = llvm::to_vector(loopOp->getOperands());
427	      for (const auto &sid : sids)
428	        newOperands.push_back(tokens[sid]);
429	      // append token type to loopOp's return type
430	      auto tokenType = cuda_tile::TokenType::get(rewriter.getContext());
431	      SmallVector<Type> resultTypes = llvm::to_vector(loopOp.getResultTypes());
432	      resultTypes.append(sids.size(), tokenType);
433	      // create new loop op
434	      rewriter.setInsertionPointAfter(loopOp);
435	      auto newLoopOp =
436	          cuda_tile::LoopOp::create(rewriter, loopOp.getLoc(), resultTypes,
437	                                    newOperands, loopOp->getAttrs());
438	
439	      // append token to loop block's argument list
440	      Block *newBlock = rewriter.createBlock(&newLoopOp.getRegion());
441	      for (Type type : loopOp.getBody()->getArgumentTypes())
442	        newBlock->addArgument(type, loopOp.getLoc());
443	      for (const auto &sid : sids)
444	        newBlock->addArgument(tokenType, loopOp.getLoc());
445	
446	      // copy block body
447	      size_t originNumArgs = loopOp.getBody()->getNumArguments();
448	      SmallVector<Value> blockArgs;
449	      for (auto arg : loopOp.getBody()->getArguments())
450	        blockArgs.push_back(newBlock->getArgument(arg.getArgNumber()));
451	      rewriter.mergeBlocks(loopOp.getBody(), newBlock, blockArgs);
452	
453	      // update token usage in loop body
454	      for (size_t i = 0; i < sids.size(); i++) {
455	        auto arg = newBlock->getArgument(originNumArgs + i);
456	        tokens[sids[i]].replaceAllUsesExcept(arg, newLoopOp);
457	        tokens.update(sids[i], newLoopOp.getResult(loopOp.getNumResults() + i));
458	      }
459	
460	      // replace old result values with new ones, except new token
461	      SmallVector<Value> replacementResults;
462	      for (size_t i = 0; i < loopOp.getNumResults(); i++)
463	        replacementResults.push_back(newLoopOp.getResult(i));
464	      rewriter.replaceOp(loopOp, replacementResults);
465	    }
466	
467	    currentBlockMemSeqs.loop_level--;
468	    return tokens.getUpdatedTokens();
469	  }
470	
471	  /// Propagates memory tokens through a block and its nested control flow.
472	  ///
473	  /// This function performs a pre-order walk of all operations in the block,
474	  /// adding memory tokens to memory operations in sequential order. For control
475	  /// flow operations (if/for/loop), it recursively processes nested blocks and
476	  /// updates tokens appropriately.
477	  ///
478	  /// @param block: The block to process.
479	  /// @param tokens: The initial tokens to propagate, the size of tokens should
480	  /// be
481	  ///                the number of sequences which requires adding memory
482	  ///                tokens.
483	  /// @param rewriter: IR rewriter for modifications.
484	  /// @param termOps: Optional collector for terminator operations with their
485	  ///                 tokens.
486	  ///         (e.g. loopOp -> ifOp -> breakOp)
487	  /// @return The final token value after processing all operations in the
488	  /// block.
489	  ///         The result will only contain the updated token value.
490	  SeqTokens addMemTokenForBlock(Block *block, SeqTokens tokens,
491	                                IRRewriter &rewriter,
492	                                OpToTokens *termOps = nullptr) {
493	    tokens.cleanUpdatedSids();
494	    if (!block || block->empty())
495	      return SeqTokens();
496	
497	    block->walk<WalkOrder::PreOrder>([&](Operation *childOp) {
498	      if (auto ifOp = dyn_cast<cuda_tile::IfOp>(childOp)) {
499	        SeqTokens newTokens = handleIfOpTokens(ifOp, tokens, rewriter, termOps);
500	        tokens.update(newTokens);
501	        return WalkResult::skip();
502	      } else if (auto forOp = dyn_cast<cuda_tile::ForOp>(childOp)) {
503	        SeqTokens newTokens = handleForOpTokens(forOp, tokens, rewriter);
504	        tokens.update(newTokens);
505	        return WalkResult::skip();
506	      } else if (auto loopOp = dyn_cast<cuda_tile::LoopOp>(childOp)) {
507	        SeqTokens newTokens = handleLoopOpTokens(loopOp, tokens, rewriter);
508	        tokens.update(newTokens);
509	        return WalkResult::skip();
510	      } else if (isMemOp(childOp)) {
511	        SeqId sid = getMemOpSeqId(childOp);
512	        auto &seq = currentBlockMemSeqs.srcToMemSeqInfoMap[sid];
513	        // only add memory token for memory op sequences with more than 1 memory
514	        // op
515	        if (!seq.ignored) {
516	          tokens.update(sid,
517	                        updateMemOpWithToken(childOp, tokens[sid], rewriter));
518	          seq.memOpCounter--;
519	        }
520	      }
521	      return WalkResult::advance();
522	    });
523	
524	    return tokens.getUpdatedTokens();
525	  };
526	
527	public:
528	  AutoGenMemoryTokenPass() = default;
529	  AutoGenMemoryTokenPass(bool enable_autogen_alias_mem_token) {
530	    this->enable_autogen_alias_mem_token = enable_autogen_alias_mem_token;
531	  }
532	
533	  void runOnOperation() override {
534	    MLIRContext *context = &getContext();
535	    ModuleOp mod = getOperation();
536	    IRRewriter rewriter(context);
537	
538	    mod->walk<WalkOrder::PreOrder>([&](Operation *outOp) {
539	      std::string fname;
540	      Block *body = getFuncBlock(outOp, fname);
541	      if (!body)
542	        return WalkResult::advance();
543	
544	      // 1. Preprocess walk: traverse the block to collect info
545	      currentBlockMemSeqs.clear();
546	      body->walk([&](Operation *op) {
547	        //    1.1 check if func/entry op contains debug_barrier op, if yes, all
548	        //    memory ops will map to the same SeqId
549	        if (isa<mlir::gpu::BarrierOp>(op)) {
550	          currentBlockMemSeqs.hasBarrierOp = true;
551	          rewriter.eraseOp(op);
552	          return WalkResult::advance();
553	        }
554	        //    1.2 record all memory ops (possibly needs to be ordered)
555	        if (!isMemOp(op))
556	          return WalkResult::advance();
557	        SeqId sid = getMemOpSeqId(op);
558	        //    1.3 check if any memory op has input token, if yes, no need to
559	        //    proceed
560	        if (currentBlockMemSeqs.hasMemToken)
561	          return WalkResult::interrupt();
562	        currentBlockMemSeqs.srcToMemSeqInfoMap[sid].memOpCounter++;
563	        if (isWriteMemOp(op))
564	          currentBlockMemSeqs.srcToMemSeqInfoMap[sid].writeMemOpCounter++;
565	        LLVM_DEBUG(llvm::errs()
566	                   << "Add Operation to SeqId " << sid << ": " << *op << "\n");
567	        return WalkResult::advance();
568	      });
569	
570	      // 2. Check phase: walk through collected info to decide whether to run
571	      // transform walk
572	      //      2.1 if no barrier op and disable autogen alias mem token, skip
573	      if (this->enable_autogen_alias_mem_token == false &&
574	          !currentBlockMemSeqs.hasBarrierOp) {
575	        return WalkResult::skip();
576	      }
577	      //      2.2 if contains user-defined mem token, skip
578	      if (currentBlockMemSeqs.hasMemToken) {
579	        if (currentBlockMemSeqs.hasBarrierOp) {
580	          outOp->emitWarning(
581	              "debug_barrier should not be added when memory tokens are added"
582	              "manually, debug_barrier op will be ignored.");
583	        }
584	        return WalkResult::skip();
585	      }
586	      //      2.3 map all mem op to a single sequence if there is debug_barrier
587	      //      op
588	      if (currentBlockMemSeqs.hasBarrierOp) {
589	        size_t writeMemOpCounter = 0, memOpCounter = 0;
590	        for (auto &p : currentBlockMemSeqs.srcToMemSeqInfoMap) {
591	          writeMemOpCounter += p.second.writeMemOpCounter;
592	          memOpCounter += p.second.memOpCounter;
593	        }
594	        currentBlockMemSeqs.srcToMemSeqInfoMap.clear();
595	        currentBlockMemSeqs.srcToMemSeqInfoMap[BARRIER_SEQ_ID] = {
596	            writeMemOpCounter, memOpCounter, false};
597	      }
598	      //      2.4 ignore sequences with only 1 memory op,
599	      //          ignore sequences with no write ops
600	      bool willModify = false;
601	      for (auto &p : currentBlockMemSeqs.srcToMemSeqInfoMap) {
602	        if (p.second.memOpCounter <= 1 || !p.second.writeMemOpCounter)
603	          p.second.ignored = true;
604	        else
605	          willModify = true;
606	      }
607	      if (!willModify) {
608	        LLVM_DEBUG(llvm::errs()
609	                   << "[AutoGenMemoryTokenPass] will not modify IR: " << fname
610	                   << ".\n");
611	        return WalkResult::skip();
612	      } else {
613	        LLVM_DEBUG(llvm::errs() << "[AutoGenMemoryTokenPass] will modify IR: "
614	                                << fname << ".\n");
615	        LLVM_DEBUG(llvm::errs()
616	                   << "[AutoGenMemoryTokenPass] Memory Sequence Info Map:\n");
617	        for (const auto &pair : currentBlockMemSeqs.srcToMemSeqInfoMap) {
618	          LLVM_DEBUG(llvm::errs()
619	                     << "\tSeqId: " << pair.first
620	                     << ", memOpCounter: " << pair.second.memOpCounter
621	                     << ", ignored: " << pair.second.ignored << "\n");
622	        }
623	      }
624	
625	      // 3. Transform walk: traverse all ops recursively in the mod again to add
626	      // memory tokens
627	      auto tokens = currentBlockMemSeqs.getBlockInitTokens(body, rewriter);
628	      addMemTokenForBlock(body, tokens, rewriter);
629	      return WalkResult::skip();
630	    });
631	  }
632	};
633	
634	} // namespace
635	
636	std::unique_ptr<Pass> mlir::triton::createAutoGenMemoryTokenPass() {
637	  return std::make_unique<AutoGenMemoryTokenPass>();
638	}
639	
640	std::unique_ptr<Pass> mlir::triton::createAutoGenMemoryTokenPass(
641	    bool enable_autogen_alias_mem_token) {
642	  return std::make_unique<AutoGenMemoryTokenPass>(
643	      enable_autogen_alias_mem_token);
644	}
